import{_ as s,o as e,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Crimson/Seastor OSD Meeting 2018-11-13","description":"","frontmatter":{"title":"Crimson/Seastor OSD Meeting 2018-11-13","date":"2018-11-13T00:00:00.000Z","updated":"2018-11-15T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","代码审查","测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Crimson_Seastor_OSD_Meeting_2018-11-13.md","filePath":"posts/2018/Crimson_Seastor_OSD_Meeting_2018-11-13.md","lastUpdated":1780460162000}'),n={name:"posts/2018/Crimson_Seastor_OSD_Meeting_2018-11-13.md"};function p(i,t,g,l,a,_){return e(),o("div",null,[...t[0]||(t[0]=[r("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2018年11月13日</p><p><strong>参会人员</strong>： 未知</p><p><strong>会议主题</strong>： Ceph 分布式存储项目进展、性能优化、代码审查与测试</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph 分布式存储项目进展</strong></p><ul><li><strong>Vasila DB Meetup</strong>： 与 Tilde 团队讨论了数据库性能分析和调试方法，了解到他们使用构建指标和 Twist Point 进行性能分析，并探讨了如何对 Ceph 进行类似分析。</li><li><strong>Rocky Beach Meetup</strong>： 参加了 Rocky Beach 年度 Meetup，了解到一家公司正在开发新的 RocksDB 版本，支持多线程和异步 I/O，这对 Ceph 的性能提升具有潜在价值。</li><li><strong>RocksDB 性能优化</strong>： 讨论了如何利用 RocksDB 的 Fiber 和单写 API 进行性能优化，并探讨了使用 Lambda 表达式进行代码优化的方法。</li><li><strong>Ceph 性能分析</strong>： 分析了 Ceph 的性能瓶颈，包括缓存污染、IO 路径复杂度等，并讨论了如何进行性能优化。</li></ul><p><strong>二、代码审查与测试</strong></p><ul><li><strong>代码审查</strong>： 审查了 Redux PR，并尝试将 Redux 的简化路径翻译到 Ceph 中。</li><li><strong>测试</strong>： 进行了 RocksDB 测试套件的测试工作，并讨论了如何使用 RocksDB 进行性能测试。</li><li><strong>调试</strong>： 讨论了如何进行 Ceph 的调试工作，包括如何处理悬挂的 Futures 和崩溃报告。</li></ul><p><strong>三、后续行动计划</strong></p><ul><li><strong>性能优化</strong>： 继续优化 Ceph 的性能，包括缓存、IO 路径、CPU 使用率等方面。</li><li><strong>代码审查</strong>： 完成 Redux PR 的代码审查工作，并尝试将 Redux 的简化路径翻译到 Ceph 中。</li><li><strong>测试</strong>： 完成 RocksDB 测试套件的测试工作，并评估 RocksDB 对 Ceph 性能的影响。</li><li><strong>调试</strong>： 完成 Ceph 的调试工作，并解决悬挂的 Futures 和崩溃报告问题。</li></ul><p><strong>四、其他</strong></p><ul><li>讨论了 Ceph 的调试符号大小问题，并探讨了如何减少调试符号的大小。</li><li>讨论了 Ceph 的内存管理问题，并探讨了如何优化内存使用。</li><li>讨论了 Ceph 的代码结构问题，并探讨了如何优化代码结构。</li></ul><p><strong>五、会议总结</strong></p><p>本次会议讨论了 Ceph 分布式存储项目的进展、性能优化、代码审查与测试等方面，并制定了后续行动计划。会议内容丰富，讨论深入，为 Ceph 项目的进一步发展奠定了基础。</p>",15)])])}const c=s(n,[["render",p]]);export{u as __pageData,c as default};
